'use strict';

function planGrid(containerWidth, minCellWidth, gap, itemIds) {
  if (!Number.isFinite(containerWidth) || !Number.isFinite(minCellWidth) ||
      !Number.isFinite(gap) || !Array.isArray(itemIds)) {
    throw new TypeError('invalid arguments');
  }
  if (containerWidth < 0 || minCellWidth <= 0 || gap < 0) {
    throw new RangeError('invalid dimensions');
  }

  const seen = new Set();
  for (const id of itemIds) {
    if (typeof id !== 'string' || id.length === 0) throw new TypeError('invalid item id');
    if (seen.has(id)) throw new RangeError('duplicate item id');
    seen.add(id);
  }

  if (itemIds.length === 0) return { columns: 0, cellWidth: 0, rows: [] };

  const columns = Math.max(1, Math.ceil((containerWidth + gap) / (minCellWidth + gap)));
  const cellWidth = (containerWidth - gap * (columns - 1)) / columns;
  const rows = [];
  for (let index = 0; index < itemIds.length; index += columns) {
    rows.push(itemIds.slice(index, index + columns));
  }
  return { columns, cellWidth, rows };
}

module.exports = { planGrid };

