'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['planGrid']);
assert.equal(typeof api.planGrid, 'function');
const { planGrid } = api;

const ids = ['a', 'b', 'c', 'd', 'e'];
const before = ids.slice();
const result = planGrid(320, 100, 10, ids);
assert.deepEqual(result, {
  columns: 3,
  cellWidth: 100,
  rows: [['a', 'b', 'c'], ['d', 'e']]
});
assert.deepEqual(ids, before);
assert.notStrictEqual(result.rows, ids);
assert.notStrictEqual(result.rows[0], ids);
assert.notStrictEqual(result.rows[0], result.rows[1]);

assert.deepEqual(planGrid(500, 100, 10, []), {
  columns: 0,
  cellWidth: 0,
  rows: []
});
assert.deepEqual(planGrid(50, 100, 10, ['x', 'y']), {
  columns: 1,
  cellWidth: 50,
  rows: [['x'], ['y']]
});
assert.deepEqual(planGrid(210, 100, 10, ['a', 'b', 'c']), {
  columns: 2,
  cellWidth: 100,
  rows: [['a', 'b'], ['c']]
});
assert.deepEqual(planGrid(200, 100, 0, ['a', 'b']), {
  columns: 2,
  cellWidth: 100,
  rows: [['a', 'b']]
});
assert.deepEqual(planGrid(0, 1, 0, ['a']), {
  columns: 1,
  cellWidth: 0,
  rows: [['a']]
});
assert.deepEqual(planGrid(250, 100, 10, ['a', 'b']), {
  columns: 2,
  cellWidth: 120,
  rows: [['a', 'b']]
});

const first = planGrid(100, 50, 0, ['a', 'b']);
const second = planGrid(100, 50, 0, ['a', 'b']);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.rows, second.rows);
assert.notStrictEqual(first.rows[0], second.rows[0]);
first.rows[0][0] = 'changed';
assert.deepEqual(second.rows, [['a', 'b']]);

const emptyFirst = planGrid(100, 50, 0, []);
const emptySecond = planGrid(100, 50, 0, []);
assert.notStrictEqual(emptyFirst, emptySecond);
assert.notStrictEqual(emptyFirst.rows, emptySecond.rows);

for (const args of [
  ['100', 10, 1, []],
  [100, '10', 1, []],
  [100, 10, '1', []],
  [NaN, 10, 1, []],
  [Infinity, 10, 1, []],
  [100, NaN, 1, []],
  [100, Infinity, 1, []],
  [100, 10, NaN, []],
  [100, 10, Infinity, []],
  [100, 10, 1, null],
  [100, 10, 1, {}],
  [100, 10, 1, [1]],
  [100, 10, 1, ['']],
  [100, 10, 1, ['a', null]]
]) {
  assert.throws(() => planGrid(...args), TypeError);
}

for (const args of [
  [-1, 10, 1, []],
  [100, 0, 1, []],
  [100, -1, 1, []],
  [100, 10, -1, []],
  [100, 10, 1, ['a', 'a']]
]) {
  assert.throws(() => planGrid(...args), RangeError);
}

